import { HistoricalDocument } from '../../types';

export const ordenacoesLivro1TitulosLxxxiAXc: HistoricalDocument = {
  id: 'ordenacoes-livro-1-titulos-lxxxi-a-xc',
  title: 'Ordenações Filipinas — Títulos LXXXI a XC',
  subtitle: 'Que se não façam scripturas per Scrivães estrangeiros',
  date: '1603',
  era: 'Idade Moderna',
  language: 'Português',
  description: `Títulos LXXXI a XC do Livro Primeiro das Ordenações Filipinas: de "Que se não façam scripturas per Scrivães estrangeiros" a "Do Curador, que he dado aos bens do absente, e á herança do defunto, a que não he achado herdeiro".`,
  parentCollectionId: 'ordenacoes-livro-1',
  sections: [
    {
      id: 'titulo-lxxxi',
      title: `LXXXI. Que se não façam scripturas per Scrivães estrangeiros`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxxi-preambulo', number: 'Preâmbulo', text: `Por se evitarem os grandes inconvenientes, que contra serviço de Deos e nosso se seguem de alguns Scrivães Castelhanos e de outras Nações, que não são Portuguezes, e outras pessoas particulares, exercitarem nestes Reinos o Officio de Scrivães, sem o serem, passando certidões, e fazendo scripturas publicas e contractos entre Portuguezes e Castelhanos, e screvendo entre partes em cousas, que não tocam à milicia: e bem assi por se não dar occasião de demandas, que sobre a nullidade das taes scripturas se podem mover: mandamos às ditas pessoas, que não façam as ditas scripturas, sob pena de se proceder contra elles confórme a nossas Ordenações. E declaramos as taes scripturas, certidões, contractos e mais papeis, de qualquer qualidade que sejam, que atégora forem feitos entre partes, e os que ao diante se fizerem, ou sobscreverem pelos ditos Officiaes Castelhanos e de outras nações, e per pessoas outras particulares, por nullos e de nenhum effeito e vigor. E mandamos, que delles se não possam as partes ajudar em tempo algum. E isto havemos assi por bem, sem embargo de quaesquer costumes e posses, em que stêm: e sem embargo de poderem allegar, que as palavras e clausulas das Cartas e Provisões de seus Ofícios se extendem a poderem nestes Reinos fazer as taes scripturas e papeis. Por quanto nossa tenção não foi essa, por serem as taes palavras e clausulas (se as houver) contra as liberdades destes Reinos, e em dano delles, e prejuizo da nossa Fazenda e das partes.` },
        { id: 'of1-tlxxxi-1', number: '1', text: `de 4 de Julho de 1585.` },
      ],
    },
    {
      id: 'titulo-lxxxii',
      title: `LXXXII. Do que hão de levar os Scrivães da Fazenda e da Camera del Rei das scripturas, que fizerem`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxxii-preambulo', number: 'Preâmbulo', text: `Querendo Nós prover ácerca do que os Scrivães da Fazenda e da Camera hão de levar das Cartas e Alvarás e outras scripturas, que fizerem, havemos por bem que levem as quantias seguintes.` },
        { id: 'of1-tlxxxii-1', number: '1', text: `Os Scrivães da Fazenda dos Padrões de juro, que pola primeira vez novamente fizerem, levarão quinhentos réis. E fazendo-se a segunda vez a pessoas, que nelles succederem per renunciação, ou per outra qualquer maneira que seja, levarão seiscentos réis, que são cem réis mais, além dos quinhentos, que hão de levar dos Padrões, que da primeira vez se fizerem. Os quaes cem réis pagará mais qualquer pessoa, que no dito juro, ou em parte delle succeder, todas as vezes que dahi em diante os ditos Padrões se fizerem, além do que até então se tiver pago do tal Padrão.` },
        { id: 'of1-tlxxxii-2', number: '2', text: `E sendo trasladados, ou incorporados em cada hum dos ditos Padrões de juro dous Padrões, levar-se-há do feitio do tal Padrão novecentos réis.` },
        { id: 'of1-tlxxxii-3', number: '3', text: `E trasladando-se nelles alguma scriptura, ou outros alguns papeis, se levará mais dos taes traslados outro tanto, quanto o Tabellião, ou Scrivão, per quem os ditos papeis foram feitos, levou dos traslados, que tirar das Notas sómente, confórme a Ordenação.` },
        { id: 'of1-tlxxxii-4', number: '4', text: `Item, dos Padrões das tenças obrigatórias separadas, e tenças em vidas, se levará quatrocentos réis de cada hum.` },
        { id: 'of1-tlxxxii-5', number: '5', text: `E indo incorporado outro Padrão, se levará mais cem réis.` },
        { id: 'of1-tlxxxii-6', number: '6', text: `E sendo dous Padrões incorporados e trasladados em hum, se levará de feitio do tal Padrão oitocentos réis.` },
        { id: 'of1-tlxxxii-7', number: '7', text: `E o mesmo salário se levará dos Padrões de tenças e Provisões, que Nós passarmos, como Governador dos Mestrados das Ordens de Nosso Senhor JESU CHRISTO, Sant-Iago e Avís.` },
        { id: 'of1-tlxxxii-8', number: '8', text: `E dos assentos, que se fizerem dos ditos Padrões de juro, tenças obrigatórias, e em vida, levará o Scrivão de nossa Fazenda ao tempo, que assentar no livro della, cem réis por cada Padrão, de qualquer quantia, que seja.` },
        { id: 'of1-tlxxxii-9', number: '9', text: `Item, dos Alvarás de tenças, que fôrem de vinte mil réis, e dahi para cima, se levará quatrocentos réis de cada hum. E sendo os ditos Alvarás de outras cou- sas, que não sejam tenças, e declarando-se nelles que valham como Cartas, se levará de cada hum, de qualquer qualidade que seja, duzentos réis. Porém sendo as taes tenças assentadas nas obras pias, se levará de cada Provisão cem réis sómente.` },
        { id: 'of1-tlxxxii-10', number: '10', text: `E dos outros Alvarás, que se fizerem, se levará sessenta réis por cada hum, não sendo de esmolas. E sendo de esmolas, se levará trinta réis de cada hum, como sempre se levou.` },
        { id: 'of1-tlxxxii-11', number: '11', text: `Item, das Cartas dos Officios, que se fizerem ás pessoas, a que delles fizerem mercê, se levarão cem réis de cada huma. E sendo as ditas Cartas feitas per renunciação, ou Alvarás de lembrança, se levará de cada huma duzêntos réis. E assi se levará cem réis do assento de cada huma das ditas Cartas.

Scrivães da Camera.` },
        { id: 'of1-tlxxxii-12', number: '12', text: `E os nossos Scrivães da Camera levarão de todas as Cartas, que fizerem em pergaminho, de Officios de Desembargadores, Corregedores, Juizes de fóra e de quaesquer outros Officios, e assi de Cartas, per que Nós fazemos a algumas pessoas de nosso Concelho, e de confirmações de cavalleiro, e para Almotacés servirem tres mezes, e para Tabelliães e Scrivães terem pessoas, que os ajudem a screver, e para Mosteiros e pessoas Ecclesiasticas possuirem bens de raiz, e para Letrados, que não tem todos os cursos, que manda a Ordenação, poderem procurar e usar de suas letras, e de quaesquer outras Cartas desta qualidade, levarão cento e cincoenta réis de cada huma.` },
        { id: 'of1-tlxxxii-13', number: '13', text: `Item, das Cartas de doações de terras, confirmações de jurisdição, Alcaidarias Móres, Cartas de privilegios e outras semelhantes, levarão quinhentos réis de cada huma.` },
        { id: 'of1-tlxxxii-14', number: '14', text: `Item, de qualquer Alvará, ou Provisão, que não for de esmola, levarão sessenta réis.` },
        { id: 'of1-tlxxxii-15', number: '15', text: `Item, de Alvará, que valha como Carta, não levando tempo limitado, levarão cem réis.` },
        { id: 'of1-tlxxxii-16', number: '16', text: `Item, de Cartas para se fazerem algumas diligencias, levarão sómente trinta réis.` },
        { id: 'of1-tlxxxii-17', number: '17', text: `E defendemos a todos os ditos Scrivães, que não levem mais dinheiro das partes pola scriptura, que fizerem, do que aqui per Nós he ordenado, postoque as partes lho queiram dar de graça. Nem levem mais dinheiro, postoque nas Cartas, ou Alvarás sejam muitas pessoas, do que levariam sendo huma só pessoa.` },
        { id: 'of1-tlxxxii-18', number: '18', text: `Outrosi mandamos aos sobreditos, que em todas as Cartas e scripturas, que fizerem, ponham as pagas, quer hajam de ser assinadas per Nós, quer per quaesquer nossos Officiaes. E quando per Nós forem assinadas, porão as pagas nas costas das Cartas no cabo dellas. E qualquer dos Scrivães, que não pozer as pagas como dito he, por a primeira vez torne á parte tudo o que levar, e mais pague o dobro para os presos: e por a segunda vez haja a dita pena do dinheiro, e seja suspenso do Officio per hum mez: e pola terceira vez haja a dita pena do dinheiro, e seja suspenso do Officio até nossa mercê. E não lhe seja recebida escusa, por dizer que por esquecimento ou pressa, ou outra fadiga o não fez. E qualquer dos ditos Scrivães, que mais levar que o conteúdo nesta Ordenação e Regimento, haverá as penas conteúdas no Livro quinto, no Titulo 72: Da pena, que haverão os Officiaes, que levam mais do conteúdo em seu Regimento.` },
        { id: 'of1-tlxxxii-19', number: '19', text: `E mandamos aos Védores da nossa Fazenda e quaesquer outros nossos Desembargadores e Officiaes, a que pertencer, que não assinem Cartas, nem Alvarás, que pagas não levarem. E ao Scrivão da Puridade, ou a qualquer pessoa, a que pertencer pôr-lhes vista, que lha não ponham; e ao Chanceller Mór, que as não selle.` },
      ],
    },
    {
      id: 'titulo-lxxxiii',
      title: `LXXXIII. Do que hão de levar os Scrivães da Corte e das Comarcas do carreto dos feitos`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxxiii-preambulo', number: 'Preâmbulo', text: `Aos Scrivães da Corte e dos Desembargadores e dos Corregedores das Comarcas e dos Ouvidores dos Infantes e de outros Senhores de terras e Mestres, e aos Scrivães dos Contadores das Comarcas, pertence haver das partes carreto dos feitos, que comsigo trazem, quando se abalam de hum lugar para outro com o Julgador, ou sem elle, por seguirem seus Officios. E se for tamanho spaço, que passe de dez legoas, levarão de carreto de cada hum feito sete réis de cada parte. E se não for maior spaço de hum lugar para outro, que dez legoas, não levem de cada feito mais que tres réis e meio de cada parte. Porém, se o spaço for tão pequeno, que não passe de cinco legoas, não leve mais de carreto do feito, que dous réis de cada parte.` },
        { id: 'of1-tlxxxiii-1', number: '1', text: `E não serão obrigados, quando se mudarem de hum lugar para outro, levar comsigo todos os feitos findos; mas pedindo-lhos as partes, e pagando-lhes suas buscas ordinarias, elles os mandarão buscar à sua custa, onde quer que os tiverem, sem por isso lhes darem mais salario per razão do dito caminho, do que acima fica dito.` },
      ],
    },
    {
      id: 'titulo-lxxxiv',
      title: `LXXXIV. Do que hão de levar os Tabelliães e Scrivães de seus Officios`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxxiv-preambulo', number: 'Preâmbulo', text: `Em todas as scripturas que se hão de contar per regras, assi como as inquirições, appellações, traslados e termos de processos, levará o Tabellião de cinco regras dous réis, e o Scrivão de cinco regras e meia: e esta maioria haverá o Tabellião mais que o Scrivão per bem da pensão, que nos paga em cada hum anno. E em cada regra haja trinta letras, pouco mais, ou menos, em modo que contando as letras de sete regras, fiquem as regras humas por outras de trinta letras. E postoque o Scrivão seja público em alguns lugares, que possa fazer scriptura pública, se nos não pagar pensão, não levará mais de cinco regras e meia dous réis, como outro Scrivão. E posto- que algum Tabellião seja privilegiado per Nós, que não pague pensão, não deixará porém de levar de cinco regras dous réis, porque sem razão seria não lhes ser util seu privilegio. E em todos os outros autos, que ao Officio de Tabellião ou Scrivão pertencem, não haja alguma outra differença, quanto ao levar dos salarios.` },
        { id: 'of1-tlxxxiv-1', number: '1', text: `E não levarão por scriptura os artigos e razoados dos Advogados e sentenças dos Julgadores, ou tenções dos Desembargadores; porque são cousas, que não screveram, e em que não tiveram trabalho, nem os Contadores lho contarão per scriptura. Porém, quando das taes cousas derem os traslados, levarão seu salario, e se lhes contará per scriptura, como levam dos mais autos.` },
        { id: 'of1-tlxxxiv-2', number: '2', text: `De huma commissão scripta no processo, per que Nós ou aquelle, que nosso lugar tiver, commetta o feito a algum Julgador, levará o Tabellião ou Scrivão sete réis daquelle, em cujo favor a commissão he feita. E se for a prazimento de ambos, ou em seu favor, levará de cada hum quatro réis, e mais não.` },
        { id: 'of1-tlxxxiv-3', number: '3', text: `Das procurações feitas apud acta levará da parte, que fizer essa procuração, sete réis, inda que faça muitos Procuradores. E se duas, ou tres pessoas fizerem hum Procurador, ou Procuradores, de cada huma pessoa levará sete réis, salvo se forem marido e molher, ou irmãos em huma herança, ou Cabido, ou Universidade, ou Concelho, que não pagarão senão como huma pessoa.` },
        { id: 'of1-tlxxxiv-4', number: '4', text: `E de todas as outras scripturas não levarão os Tabelliães, nem Scrivães, posto que sejam de nossa Corte, ou das correições, ou outros quãesquer de nossos Reinos e Senhorios mais, postoque em ellas sejam muitas pessoas, do que direitamente lhes pertence levar, sendo huma só pessoa.` },
        { id: 'of1-tlxxxiv-5', number: '5', text: `De querela, fiadoria, convença, ou outro termo semelhante, que screveren perame algum Julgador, ou per seu mandado forem fazer em algum lugar dentro na villa, ou arrabalde, onde o Julgador stiver, levarão sete réis, assi como levam de huma assentada de testemunhas. E Desde a promulgação das Ordenações até o presente os salarios e custas da Justiça têm constantemente crescido.

mais haverão o que montar nessas scripturas, que fizerem, contadas as regras, como dito he.` },
        { id: 'of1-tlxxxiv-6', number: '6', text: `E de qualquer termo, em que for scripta revelia, e fizer menção, como a parte foi apregoada, levarão da parte, em cujo favor se fizer o termo, sete réis.` },
        { id: 'of1-tlxxxiv-7', number: '7', text: `E das publicações das sentenças difinitivas levarão quatorze réis: e das interlocutorias sete réis da parte, em cujo favor forem. E se a sentença fizer por ambas as partes, pagará cada huma, segundo a sentença, ou interlocutoria for em seu favor.` },
        { id: 'of1-tlxxxiv-8', number: '8', text: `E das conclusões assi sobre o libello, ou sobre artigos, ou sobre a difinitiva, ou sobre outra qualquer cousa, de cada huma conclusão levarão quatro réis: convém a saber, dous réis de cada huma parte. E se tal conclusão for á revelia de huma das partes, levarão a revelia e a conclusão da parte, em cujo favor he a conclusão e revelia. Porém, se for conclusão ante o Juiz da appellação, e for sobre a difinitiva, se esse Scrivão não houve do feito vista, ou outro proveito de scriptura, salvo a dita conclusão como muitas vezes acontece, assi em feitos crimes, como civeis, levarão o Scrivão de tal conclusão trinta e seis réis: convém a saber, dezoito de cada parte. E se não apparecer senão huma parte, e for conclusão á revelia da outra, levarão dezoito réis dessa parte, que for presente, e mais a revelia daquella, em cujo favor he.` },
        { id: 'of1-tlxxxiv-9', number: '9', text: `E dos mandados, que o Julgador mandar, assi como quando assinar termo a alguma das partes, a que venha razoar, ou venha com alguma scriptura, ou lhe mandar dar o traslado de algumas razões, ou o lançam da prova, ou das razões, ou de outra cousa, ou outros semelhantes mandados, levarão da parte, em cujo favor for tal mandado, quatro réis.` },
        { id: 'of1-tlxxxiv-10', number: '10', text: `E das inquirições, que tomarem, além daquillo, que lhes montar da scriptura contada ás regras, levarão as assentadas das testemunhas per esta maneira: de cada huma assentada sete réis, e do dito das testemunhas não levarão cousa alguma, salvo sua scriptura. E estas assentadas sejam taes, que em cada huma haja tres ditos de testemunhas; e se menos for, não lhes contem assentada, salvo dous réis do dito da testemunha e sua scriptura, e farão duas assentadas no dia, convém a saber, huma da hora da terça até ao meio dia, e outra depois de comer até a saida de vespera. E starão prestes para receber quantas testemunhas podérem no dito tempo em cada assentada. E porque ás vezes em huma assentada o Tabelliáo, ou Scrivão toma quatro, ou cinco testemunhas, e em outra não toma mais de huma, ou duas, o que acontece, ou polas testemunhas dizerem muito, ou pouco, ou a parte por então não poder dar mais, e não por culpa do Tabelliáo, ou Scrivão, em este caso refaçam-se as testemunhas de huma assentada pela outra, de maneira que leve de cada tres testemunhas huma assentada. E isto se entenda, quanto ás testemunhas, que tirar em lugar acostumado; e se forem pela villa perguntar testemunhas em suas casas, por serem pessoas honradas, ou enfermas, que mereçam e devam ser perguntadas em suas casas, ou andarem tirando algumas inquirições devassas pelas Freguezias, levem de cada tres testemunhas por huma assentada, assi como se as perguntassem em lugar acostumado, porque tão grande trabalho he de as andar assi perguntando, como star residente em certo lugar.` },
        { id: 'of1-tlxxxiv-11', number: '11', text: `Das penhoras, que fizerem, quando forem com o Porteiro, levarão o que se lhes montar na scriptura, que screverem, contada ás regras, como dito he, e mais de ida sete réis. E outro tanto levarão, quando stiverem á venda dos penhores, cada vez que hi stiverem, convém a saber, cada dia duas vezes, huma até jantar, e outra depois de comer até vespera, se tanto durar a venda dos penhores. E se a parte penhorada quizer pagar, e lhe tornarem esses penhores, levarão o Tabelliáo, ou Scrivão a scriptura, que sobre isso screver, contada ás regras, e mais de sua entrega sete réis. E isto se entenda, quando a penhora for feita na villa, ou arrabalde do lugar, onde o Tabelliáo stiver, porque se mais longe for, levarão maior salario, como se ao diante dirá.` },
        { id: 'of1-tlxxxiv-12', number: '12', text: `E da sentença, ou instrumento, que fizerem, se fór tirada do processo, ou de instrumento de aggravo, e for huma meia folha de papel cheia, scripta de ambas as bandas, levará della cincoenta e oito réis. E se for scripta de huma só banda, levará vinte nove réis, e assi por esse respeito, segundo sua quantidade. E se for Carta testemunhavel, ou outra direita, assi como Carta de seguro, ou de posse, ou de inimizade, ou Carta, feita per petição, que não são de muito trabalho, levarão de huma meia folha cheia, scripta de ambas as bandas, quarenta e quatro réis. E se for scripta de huma só banda, levarão vinte e dous réis. E assi do menos a esse respeito, com tanto que cada huma banda leve vinte cinco regras, pouco mais, ou menos, em modo que contando quatro, ou cinco bandas, sejam em humas por outras vinte cinco regras em cada huma banda. E assi cada regra levará ao menos trinta letras, em modo que contando as letras de sete, ou oito regras, fiquem humas por outras de trinta letras cada huma. E não havendo em cada banda as regras pelo sobredito modo, não lhas contarão senão ás regras, a cinco regras por dous réis. E não sendo as regras das letras, que dito he, não lhe contarão dellas cousa alguma.` },
        { id: 'of1-tlxxxiv-13', number: '13', text: `E as Cartas testemunhaveis, ou direitas, instrumentos de aggravo, appellações e outras scripturas, de qualquer sorte que sejam, não as façam em bandeira, ou rolo, nem as screvam ao longo, sómente as façam da maneira que se screvem no processo. E fazendo-as de outra maneira, percam toda a scriptura, que assi fizerem.` },
        { id: 'of1-tlxxxiv-14', number: '14', text: `E quando algum Tabellião, ou Scrivão fizer alguma Carta testemunhavel, ou instrumento de aggravo, ou outra qualquer Carta, que nosso sello levar, ser-lhe-hão contadas as primeiras tres folhas, que são seis laudas, a quarenta e quatro réis cada lauda. E se cada huma das ditas scripturas for de mais folhas, contar-lhe-hão todas as mais folhas e scripturas ás regras, a cinco regras por dous réis ao Tabellião, e cinco e meia ao Scrivão, sendo sempre as ditas folhas das regras e letras sobreditas. E quanto he ás appel- lações, contar-lhas-hão todas desde principio ás regras.` },
        { id: 'of1-tlxxxiv-15', number: '15', text: `E quando taes scripturas vierem á nossa Corte, ou á Relação do Porto, seja contado aquillo, que se dellas montar aos Tabelliães e Scrivães, que as fizerem, pela sobredita maneira; e aquillo, que for achado que mais levaram, sendo ahi moradores, o Contador das custas os faça logo chamar, e logo com effeito tornar ás partes em dobro. E se forem moradores em outra parte, faça-se Carta, passada pelos Desembargadores, que do feito conhecerem, para que tudo assi seja realmente executado. E mais haverão a pena conteuda no quinto Livro, no Título 72: Da pena, que haverão os Officiaes, que levam mais, etc., da qual se tirará o que assi a parte levar, segundo mais largamente ahi diremos.` },
        { id: 'of1-tlxxxiv-16', number: '16', text: `Dos Alvarás pequenos, que não encherem huma lauda, assi como Alvarás para prender e soltar presos, ou para citar testemunhas, ou de outros semelhantes, levem quatorze réis de cada hum. Porém, se o Alvará for tão grande, que encha huma lauda, levem delle hum vintem, e a esse respeito, se mais for.` },
        { id: 'of1-tlxxxiv-17', number: '17', text: `E dos feitos dos presos pobres, que se livram pelas Misericordias do Reino, não levarão os Scrivães mais aos ditos presos, que ametade do salario, que lhes pertencer, ou sejam Scrivães da nossa Corte, ou outros quaesquer do Reino.` },
        { id: 'of1-tlxxxiv-18', number: '18', text: `E havemos por bem, que os Scrivães, que screvêrem nos feitos dos livramentos dos presos degradados para galés, assi nas terras, donde vem os ditos degradados, como nas Casas da Supplicação e do Porto, não levem mais que a terça parte daquillo, que lhes for contado de sua scriptura nos ditos feitos.` },
        { id: 'of1-tlxxxiv-19', number: '19', text: `E os Tabelliães e Scrivães porão per sua mão as pagas em todas as ditas scripturas, que fizerem, de que devam levar dinheiro. E nas de que não houverem, ou não quizerem levar dinheiro, ponham nihil. E na Carta não ponham paga de publicação, nem de processo, mas sómente do que levarem pola scriptura da Carta.

E o que o contrario fizer, não pondo para, como dito he, pola primeira vez torne à parte todo o que levar, e pague outro tanto para os presos. E pola segunda vez haja a mesma pena, e seja suspenso do Officio per seis mezes; e pola terceira seja privado do Officio.

Vistos.` },
        { id: 'of1-tlxxxiv-20', number: '20', text: `Da vista do feito o Tabellião, ou Scrivão que o screver do principio, levará asexta parte de quanto montar na scriptura da inquirição do tal feito, até onde a vista for pedida, contando-a toda às regras na sobredita maneira. E postoque a vista seja pedida muitas vezes, não levará vista, senão huma só vez. Porém, se depois que a vista for pedida huma vez, o feito crescer mais per inquirição, ou per scriptura, qualquer que seja, seja-lhe contada a vista do que mais crescer, depois que a outra vista foi pedida: com tanto que lhe não contem vista, donde lhe contaram o traslado.` },
        { id: 'of1-tlxxxiv-21', number: '21', text: `E perante o Juiz da appellação levará o Scrivão da vista dessa appellação dous réis de cada folha. Porém, se o Juiz da appellação mandar tirar algumas inquirições nesse feito, depois de pender perante elle, ora se tirem na Corte, ora em outra parte, e for dellas pedida vista, levará o Scrivão o sexto dellas, assi como se o feito fosse começado perante o Juiz da appellação.` },
        { id: 'of1-tlxxxiv-22', number: '22', text: `E sendo hum feito findo per sentença, se depois for alguma parte dado em outro feito em ajuda de seu direito, e for delle pedida vista per alguma parte, de tal feito não levará o Tabellião, ou Scrivão vista, salvo ametade do que levou o Scrivão perante o Juiz da appellação; porquanto já do feito findo esse Tabellião ou Scrivão, que o tinha, levou a vista. Porém, se ainda delle não houve alguma vista, e então foi a primeira vez que se pedio, levará sua vista toda per inteiro, assi do feito, como da appellação, pela maneira que dito he. E desta vista levará ametade o Tabellião ou Scrivão, que tinha o feito, que he dado em prova.

Buscas.` },
        { id: 'of1-tlxxxiv-23', number: '23', text: `Todo o Tabellião, ou Scrivão, que tiver feito em seu poder, depois que for findo per sentença, ou antes que o seja, se he retardado, e não se falia a elle per culpa das partes, quando per alguma dellas lhe for requerido, que o traga a Juizo para fallar a elle, ou para tirar delle sentença, ou outra scriptura, ou para o dar em ajuda de sua prova em outro feito, ou para haver per elle algum proveito, levará esse Tabellião, ou Scrivão da busca de tal feito de cada mez, nove réis, e isto até o primeiro anno cumprido, que são per anno cento e oito réis. E se fôr mais tempo, que passe de anno, levará no segundo anno cincoenta e quatro réis. E se passar de dous annos, levará polo terceiro anno dezoito réis. E se passar de tres annos, não levará dahi em diante de busca mais cousa alguma, mas levará sómente dos ditos tres annos, em que se montam cento e oitenta réis. A qual busca se lhe dá, não sómente polo trabalho, que leva em buscar o feito, mas porque he obrigado guardar os feitos crimes até vinte annos, e até trinta os civeis.` },
        { id: 'of1-tlxxxiv-24', number: '21', text: `E tal busca, como esta, não haverá lugar nas scripturas, que a parte deu em Juizo para provar sua tencão, que sejam taes, que no fim do feito se devam tornar à parte, postoque o Tabellião, ou Scrivão as tenha em seu poder o dito tempo, durando o feito.` },
        { id: 'of1-tlxxxiv-25', number: '22', text: `E depois que o feito for findo per sentença, se a parte não requerer suas scripturas, e as deixar star em casa desse Tabellião, ou Scrivão, leve dellas busca, assi como de outro feito, ou scripturas, que tiver em sua guarda, pela sobredita maneira: salvo se a parte não for na terra para as pedir e requerer. E esta busca haverá lugar em todos os processos, inquirições e scripturas, que esse Tabellião ou Scrivão tiver em sua guarda, como dito he. Porém, se for requerido, que dê as ditas scripturas, e maliciosamente por levar busca as retiver, não haverá dellas busca e pagará à parte outro tanto, quanto lhe pedir de busca.` },
        { id: 'of1-tlxxxiv-26', number: '26', text: `E quanto às scripturas, que ha de buscar per livro, assi como Notas de contractos, querelas, ou denunciações, que tenham scryptas em seus livros, de taes como estas levarão de busca sómente ametade do que levariam dos processos e scripturas acima ditas, havendo respeito ao que dito he; e outro tanto levará o Tabellião por buscar o instrumento, que já tiver tirado da Nota, e não lhe foi requerido pela parte a que pertencia, pois não steve per o Tabellião.` },
        { id: 'of1-tlxxxiv-27', number: '27', text: `E dos inventarios feitos pelos Tabelliães dos bens dos orfãos, onde não houver Scrivães do dito Officio, levarão de busca o que he declarado no Título 89: Dos Scrivães dos Orfãos.` },
        { id: 'of1-tlxxxiv-28', number: '28', text: `E em todos os sobreditos casos, onde devem haver busca, não se contará busca dos primeiros seis mezes, mas contar-se-ha do tempo que correr depois delles; por que depois que passam os ditos seis mezes, sem se fallar ao feito, não stando concluso, ou stando concluso hum anno na mão do Scrivão sem se fallar a elle, não se póde fallar ao feito, até que a parte seja novamente citada.

Idas.` },
        { id: 'of1-tlxxxiv-29', number: '29', text: `E quando algum Tabellião, ou Scrivão for fóra do lugar tirar inquirição, ou fazer outro negocio, se levar besta sua e moço, levará para si e para mantimento da besta e moço dous tostões por cada dia, que andar fóra de sua casa. E haverá mais sua scriptura e assentada de testemunhas, ou a penhora, se a fizer. E se em tal negocio não andar senão ametade de hum dia, levará ametade; e assi mais, ou menos, segundo o spaço do dia, que lá andar. Porém, se a parte dér besta sua a esse Tabellião ou Scrivão, não levará mais que hum tostão para si e para mantimento do moço. E não comerá o dito Tabellião, ou Scrivão com a parte, por se não dar azo de se afeiçoar a ella, salvo se no lugar, onde o tal negocio for fazer, não achar a vender outro mantimento, senão o que lhe a parte dér. E se comer á custa da parte, elle, o moço e a besta, não levará mais que hum tostão. E se não levar besta, haverá sómente hum tostão, e comerá á sua custa. E se comer á custa da parte, não levando besta, haverá meio tostão sómente; e o mesmo levarão os Enquerredores.` },
        { id: 'of1-tlxxxiv-30', number: '30', text: `E sendo as partes presentes no lugar, onde os Tabelliães, ou Scrivães forem moradores, demandem seus salarios do dia que se publicar a sentença diffimitiva, a trez mezes. E não os demandando no dito tempo, não os possam mais demandar, nem sejam sobre isso mais ouvidos. E os ditos Officiaes serão avisados, que não levem mais cousa alguma além do que lhes he taxado, sob pena de perdimento de seus Officios. E haverão as mais penas conteúdas no Livro quinto, no Título 72: Da pena; que haverão os Officiaes, que levam mais do conteúdo em seu Regimento.` },
      ],
    },
    {
      id: 'titulo-lxxxv',
      title: `LXXXV. Dos Distribuidores das cidades, villas e lugares do Reino`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxxv-preambulo', number: 'Preâmbulo', text: `Ordenamos que nos lugares, onde houver dous Tabelliães do Judicial, ou mais, haja hum Distribuidor, que distribua entre elles todos os feitos, Cartas, desembargos e autos, que a elles pertence fazer, em maneira que sejam igualados nos feitos e scripturas, que fizerem. E será obrigado ter livro de distribuição encadernado, e o guardar e dar conta delle até trinta annos. E onde houver Officios de Contador, Enqueredor e Distribuidor, andarão todos tres em huma só pessoa. E o salario do Officio de Enqueredor lhe será contado pelo Juiz, e não per Tabellião algum, nem outro Official de Justiça.` },
        { id: 'of1-tlxxxv-1', number: '1', text: `E onde houver dous Tabelliães das Notas, ou mais, distribuirá entre elles o Distribuidor dos Tabelliães do Judicial. Porém nos lugares onde houver muitos Tabelliães das Notas, haverá hum Distribuidor apartado do dos Tabelliães do Judicial; o qual será obrigado star no Paço dos Tabelliães das Notas tres horas pela manhã, e tres à tarde continuadamente. E o Distribuidor, que distribuir as scripturas entre os Tabelliães das Notas, assentará no livro da distribuição os nomes das partes, que fizerem os contractos, e as cousas sobre que se fazem, dizendo: Item a N. e N. Tabellião huma scriptura de venda de humas casas que N. vendeo a N.` },
        { id: 'of1-tlxxxv-2', number: '2', text: `E quando as scripturas se forem fazer fóra do Paço dos Tabelliães, e nenhuma das partes for lá para o declarar, o Distribuidor carregará na Distribuição a scriptura ao Tabellião, que a houver de ir fóra fazer, pondo o nome sómente do que o manda chamar. E deixará em branco spaço, para depois screver os nomes das outras partes e substancias das scripturas, como acima dito he. E o dito Tabellião no mesmo dia até o outro seguinte, a mais tardar, declarará ao Distribuidor, sob pena de perder o Officio, os nomes das partes e a substancia do contracto. E não o fazendo assi, o Distribuidor lhe não dará mais distribuição.` },
        { id: 'of1-tlxxxv-3', number: '3', text: `E se depois de ser distribuida a scriptura a algum Tabellião das Notas para a fazer, as partes se arrependerem, ou per alguma maneira a não quizerem fazer, o Tabellião, a que assi for distribuida, o notificará dentro em dous dias ao Distribuidor: o qual assentará na margem, onde a tal scriptura stiver distribuida, como o dito Tabellião disse que a não fizera, e o Tabellião assinará ao pé, e lhe será depois dada outra tal na distribuição. E não o notificando no dito termo, postoque depois queira provar que as partes não fizeram tal scriptura, não será a ello recebido. Porém no caso, em que o Tabellião fizer a scriptura, que lhe for distribuida, se disser ao Distribuidor que a não fez, será punido como falsario.` },
        { id: 'of1-tlxxxv-4', number: '4', text: `E quando o Distribuidor dos Tabelliães do Judicial for doente, ou em tal maneira impedido, que não possa servir, ou per qualquer maneira não for fazer a distribuição, o Juiz porá hum Tabellião da audiencia, que lhe melhor parecer, que por elle sirva, emquanto o impedimento durar, ou per Nós não fôr provido. E quando o Distribuidor das Notas for impedido, o Juiz dará hum Tabellião das Notas que faça a distribuição, emquanto o impedimento durar como dito he.` },
        { id: 'of1-tlxxxv-5', number: '5', text: `E os Distribuidores levarão de cada cousa, que distribuirem, seis réis. E não levarão busca, senão quando passar de cinco annos, que o feito, auto, ou scriptura forem distribuidos.` },
      ],
    },
    {
      id: 'titulo-lxxxvi',
      title: `LXXXVI. Dos Enqueredores`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxxvi-preambulo', number: 'Preâmbulo', text: `Cumpre advertir que he mister que a testemunha toque nos Santos Evangelhos, não bastando que diga o Escrivão que a testemunha jurou. Só he permitido não tocar nos Evangelhos aos Cardeaes e Bispos.

Atente-se à expressão da lei — Santos Evangelhos, e não Biblias hereticas, de que infelizmente se usa em muitos tribunaes do Brasil.

perante a parte, contra quem he chamada, se ella a quizer ver jurar; do qual juramento o Tabellião, ou Scrivão dará sua fé no dito da testemunha que screver. E depois que assi jurar, dará seu testemunho secretamente, sem nenhuma das partes delle ser sabedor, até as inquirições serem abertas e publicadas. E assi as perguntará logo polo costume e cousas, que a elle pertencem, convem a saber, se tem divido ou cunhadio com alguma das partes, e em que grão, e se tem tão estreita amizade, ou odio tão grande a alguma dellas, por que deixem de dizer a verdade. E se receberam de alguma dellas ou de outrem em seu nome algumas dadivas, e se foram rogadas, ou subornadas, que dissessem em favor de alguma das partes: e lhes perguntarão por suas idades. E tudo o que disserem screverá o Tabellião, ou Scrivão, que a inquirição screver. Polo qual costume perguntarão sempre as testemunhas, sob pena de perdimento dos Officios, assi nas inquirições devassas, como judiciaes. Porém nas inquirições devassas geraes, ou particulares perguntarão polo costume no fim do testemunho.` },
        { id: 'of1-tlxxxvi-1', number: '1', text: `E bem assi perguntarão declaradamente polo que sabem dos artigos, e não perguntarão por cousa alguma, que seja fóra do que nelles se contém, e da materia e caso delles. E se disserem, que sabem alguma cousa daquillo, por que são perguntados, perguntem-lhes como o sabem. E se disserem, que o sabem de vista, perguntem-lhes em que tempo e lugar o viram, e se stavam ahi outras pessoas, que tambem o vissem. E se disserem que o sabem de ouvida, perguntem-lhes a quem o ouviram, e em que tempo e lugar. E todo o que disserem, façam screver, fazendo-lhes todas as outras perguntas, que lhes parecerem necessarias, per que melhor e mais claramente se possa saber a verdade. E attentem bem com que aspecto e constancia fallam, e se variam, ou vacillam, ou mudam a côr, ou se torvam na falla, em maneira, que lhes pareça, que são falsas, ou suspeitas. E quando assi o virem, ou sentirem, devem-no notificar ao Julgador do feito, se for no lugar onde se tirar a inquirição: e se for absente, mandarão aos Scrivães, ou Tabelliães que screvam as ditas torvações e desvarios das testemunhas, a que acontecer, para o Juiz, que houver de julgar o feito, prover nisso, como lhe parecer justiça. E fazendo outras perguntas afóra as conteúdas nesta Ordenação, ou não fazendo todas estas por este mesmo feito o Enqueredor perca o Officio, e nunca mais o haja; e o Tabellião ou Scrivão que as screver, seja suspenso até nossa mercê. E postoque a testemunha queira dizer mais do conteúdo no dito artigo, ou da substancia e caso delle, ainda que lhe não seja perguntado, o Tabellião, ou Scrivão o não screva sob a mesma pena.` },
        { id: 'of1-tlxxxvi-2', number: '2', text: `E será avisado o Scrivão, ou Tabellião, que a inquirição com algum Enqueredor tirar, que quando a testemunha disser de algum artigo ou artigos, nihil, não screva nem ponha em cada artigo particularmente: Perguntando por tal artigo, e feita pergunta, que era o que dello sabia, etc., disse nihil: Sómente em hum só capitulo, no fim do testemunho. E depois de acabar de screver todos os artigos, em que a testemunha disse alguma cousa, fará hum capitulo, em que dirá assi: E perguntado por tal artigo, e tal, declarando-os sómente por numero, assi como, primeiro, segundo e terceiro, a todos disse nihil. E o Tabellião, ou Scrivão, que o contrario fizer, será suspenso do Officio até nossa mercê.` },
        { id: 'of1-tlxxxvi-3', number: '3', text: `E quando se houverem de tirar inquirições judiciaes sobre casos de morte, ou aleijão, ou de ferimento de rosto com desformidade delle, ou de furto, que provado mereça pena de morte, os Julgadores das ditas causas, se nos lugares, onde se os feitos tratarem, se tirarem as ditas inquirições, as tirarão per si. E não se tirando nos mesmos lugares, onde se os feitos tratarem, e havendo-se de passar Cartas para outros lugares, para nelles se tirarem, os Julgadores a que forem dirigidas, as tirarão per si. E o mesmo será nos casos civeis de quantidade, ou valia de cem cruzados, ou dahi para cima, pedindo-o alguma das partes, ou seu Procurador. E se as partes forem contentes, ou não contrariarem, que as inquirições nos ditos casos civeis se tirem per Enqueradores, tirar-se-hão per elles, e serão valiosas, como se fossem tiradas pelos ditos Julgadores. E em cada hum dos sobreditos casos, em que os Julgadores perguntarem per si as testemunhas, levarão o salario, que adiante diremos, que levem os Enqueredores.` },
        { id: 'of1-tlxxxvi-4', number: '4', text: `E os Enqueredores não tirarão as inquirições sobre Jugadas, Rendas, e Direitos Reaes; porque havemos por bem, que as tirem os Juizes dos ditos Direitos, ou os Almoxarifes, onde elles dos ditos Direitos conhecerem, nos feitos, que pe- rante elles se tratarem, postoque seja sobre pequena quantia, quer os ditos Direitos se tirem para Nós, quer para quem de nossa mão os tiver. Os quaes as tirarão per si com os Scrivães dos feitos, e não as commetterão aos Enqueredores. E se as taes inquirições se não houverem de tirar nos lugares, onde elles forem Juizes, dirigirão as Cartas para os Juizes dos Direitos Reaes, ou Almoxarifes, se os houver nos lugares, onde se hão de tirar as inquirições. E não os havendo, irão para os Juizes de fóra, ou ordinarios; aos quaes mandamos que as tirem per si, sem as commetterem aos Enqueredores, para mais segurança da justiça das partes. E a mesma maneira se terá nas Cartas de inquirições sobre Direitos Reaes e Jugadás, que se passarem nas Relações das Casas da Supplicação e do Porto.` },
        { id: 'of1-tlxxxvi-5', number: '5', text: `Por se evitarem testemunhos falsos, que na Comarca de Entre Douro e Minho se dão, mandamos que as Cartas, que se passarem para os presos, ou seguros da dita Comarca, cujos feitos vão ás Relações per appellação, provarem suas defesas, contraditas, ou excepções de ordens, vão dirigidas aos Corregedores e Juizes de fóra, que na primeira instancia conheceram dos casos, por terem informação delles, e não para os Juizes dos Concelhos, onde os taes presos, ou seguros são moradores. E querendo elles fazer suas provas em outras partes, que não forem da jurisdição dos taes Corregedores e Juizes de fóra, elles mandarão vir perante si as testemunhas à custa das partes, que a prova quizerem fazer. E elles per si as perguntarão, sem as commetterem a outrem, e assi se declarará nas ditas Cartas.` },
        { id: 'of1-tlxxxvi-6', number: '6', text: `E todos os Enqueredores levarão de cada assentada de testemunhas sete réis, e de cada dito de testemunha outros sete réis sómente.` },
        { id: 'of1-tlxxxvi-7', number: '7', text: `E se for fóra do lugar tirar alguma inquirição, levará as assentadas e ditos das testemunhas, e o mais conteúdo no título 84: Do que hão de levar os Tabelliães, no paragrapho 29: E quando algum, que guardará, como em elle se contém.

E essa péssima fama os priva ainda de certas graças, quando condenados à degredo. Ord. de liv. 5 t. 132 § 5.` },
      ],
    },
    {
      id: 'titulo-lxxxvii',
      title: `LXXXVII. Do que hão de levar os Porteiros e Pregoeiros`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxxvii-preambulo', number: 'Preâmbulo', text: `Os Porteiros, quando fizerem as penhoras no lugar, onde forem moradores, ou no arrabalde delle, levarão de cada penhora dez réis. E quando se arrematarem os penhores, levarão de quanto montar na venda delles, se forem moveis, de cincoenta réis hum, até que possam haver de seu salario cento e oitenta réis; e não levarão mais, ainda que a quantia da arrematação seja grande e dure muito. E se esses penhores não forem arrematados, e a parte per sua vontade logo pagar, levarão da entrega delles dez réis, quando os entregarem à parte. Porém, se os trouxerem em pregão o tempo conteúdo na Ordenação, ou algum pouco menos, e não os arrematarem, levarão ametade do que levariam, se arrematados fossem. E se a penhora for feita pelo Porteiro, e elle não vender os penhores, e os vender o Pregoeiro, leve o Porteiro sua penhora, e o Pregoeiro sua arrematação. E se a penhora for feita em bens de raiz, leve de sua penhora dez réis, e da arrematação de cincoenta réis hum, até que chegue a trezentos e sessenta réis; e mais não, postoque os bens muito valham.

Nenhum lexicographo fixa, pouco mais ou menos, à área que occupa tal povoado.` },
        { id: 'of1-tlxxxvii-1', number: '1', text: `E mandamos, que esta taxa e ordenança tenhàm os Sacadores, e per esta maneira levem o seu salario, e assi lhes seja contado, e não de outra: e assi ás Adélas dos penhores e cousas, que lhes dão a vender. E qualquer das sobreditas pessoas, que mais levar da parte, do que aqui lhe he ordenado e taxado, haverá as penas conteúdas no quinto Livro, Titulo 72: Da pena, que haverão os Officiaes, que levem mais do conteúdo em seu Regimento.` },
        { id: 'of1-tlxxxvii-2', number: '2', text: `E tudo o que dito he dos salarios dos Porteiros e Pregoeiros, queremos, que haja lugar, quando venderem alguns bens per mandado dos herdeiros e Testamenteiros dos defuntos e Curadores e Administradores de bens, ou de outras quaesquer pessoas, que lhos mandarem vender. E quando esses Porteiros forem fóra do lugar fazer as penhoras, levarão por cada legua de ida e vinda hum vintem, afóra o que lhes montar de sua penhora, ou entrega. E das citações haverão o que he ordenado no Titulo 31: Dos Porteiros dos Corregedores da Corte.` },
      ],
    },
    {
      id: 'titulo-lxxxviii',
      title: `LXXXVIII. Dos Juizes dos Orfãos`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxxviii-preambulo', number: 'Preâmbulo', text: `Antigamente o prover sobre as pessoas e fazendas dos Orfãos pertencia aos Juizes ordinarios e Tabelliães, e por suas occupações serem muitas, e não poderem cumprir com esta obrigação, como devíam, foram ordenados os Officios de Juiz e Scrivão dos Orfãos, para specialmente proverem nas pessoas e fazendas delles, no que devem ter grande cuidado, pola muita confiança, que nelles he posta. E em todas as villas e lugares, onde nelles e no termo houver quatrocentos visinhos, ou dahi para cima, mandamos que haja Juiz dos Orfãos apartado (i). E onde não houver o dito numero de visinhos, os Juizes ordinarios sirvam o Officio de Juiz dos Orfãos com os Tabelliães da villa: salvo se nas villas e lugares, que a quatrocentos visinhos não chegarem, houver costume e posse antiga Nessa legislação se achão consignadas todas as obrigações dos Porteiros nos Auditorios Commerciaes de 1ª instancia.

de haver Juiz dos Orfãos, ou forem per Nós ordenados. Os quaes Juizes ordinarios serão obrigados cumprir e guardar em tudo o conteúdo neste titulo, sob as penas nelle declaradas.` },
        { id: 'of1-tlxxxviii-1', number: '1', text: `E o que houver de ser Juiz dos Orfãos, será de trinta annos, e dahi para cima. E servindo, não sendo da dita idade, ora a dada seja nossa, ora da Camera, ou de algum Senhor de terras, perca o Officio, e nunca o mais haja; e Nós o daremos a quem nossa mercê for; e mais perderá ametade de sua fazenda.` },
        { id: 'of1-tlxxxviii-2', number: '2', text: `E nenhum Juiz dos Orfãos, nem Scrivão delles, em quanto o forem, será Juiz ordinario, ainda que o queira ser.

Ora, o exercício do voto he a primeira funcção publica que exerce o cidadão; e se não póde desempenhar a antes da idade de 25 annos, he claro que menos poderia exercer outras por sem duvida mais complicadas.

« He de Direito Publico Brasileiro que não podem servir Officios Publicos os menores de 25 annos. »` },
        { id: 'of1-tlxxxviii-3', number: '3', text: `E o Juiz dos Orfãos deve com grande diligencia e cuidado saber quantos Orfãos ha na cidade, villa, ou lugar, em que he Juiz, e fazel-os todos screver em hum livro ao Scrivão desse Officio, declarando o nome de cada Orfão, e cujo filho he, e de que idade, e onde vive, e com quem, e de quem he seu Tutor, e Curador. E deve saber quantos bens tem moveis e de raiz, e quem os traz, e se andam bem aproveitados, danificados, ou perdidos, e por cuja culpa e negligencia, para os poder fazer aproveitar e arrecadar. E assi deve fazer pagar aos Orfãos toda a perda e dano, que em seus bens receberam, por aquelles que nisso achar negligentes, ou culpados. E o Juiz, que o assi não cumprir, pagará aos ditos Orfãos toda a perda e dano, que por isso receberem.

Inventários.` },
        { id: 'of1-tlxxxviii-4', number: '4', text: `E tanto que fallecr algum, que tenha filho, ou filhos menores de vinte cinco annos, o Juiz dos Orfãos terá cuidado, do dia de seu fallecimento a hum mez, fazer inventario de todos os bens moveis e de raiz, que por morte do defunto ficarem. E dará juramento à pessoa, em cujo poder ficarem os ditos bens, que faça inventario de todos elles, bem e verdadeiramente, declarando as confrontações dos bens de raiz, e o lugar, onde stão; e dos moveis porá taes sinaes, per que em todo o tempo se possam conhecer, e não haja sobre elles duvida. E assi se porão no dito inventario todas as dividas, que se deverem a esses Orfãos, ou em que elles a outrem forem devedores. E se algumas cousas alheias ahi forem achadas, declare-se cujas são, e per que modo vieram a poder do defunto, e se tem os Orfãos algum direito nellas, para se saber o que lhes fica, ou póde ficar por fallecimento de seu pai; e logo então se farão as partilhas das taes fazendas ordenadamente. E assi farão declarar no inventario todas as scripturas, que aos Orfãos pertençam, declarando sómente o de que cada huma scriptura he; e o nome do Tabelliào, ou Scrivão, que a fez, e quando, para se saber em todo o tempo, quaes e quantas scripturas ficaram, e para o Tutor dar dellas conta, porque os proprios lhes hão de ser entregues pelo dito inventario.` },
        { id: 'of1-tlxxxviii-5', number: '5', text: `E para que os Orfãos não recebam perda, mandamos que logo ao tempo, em que os inventarios e partilhas se fizerem, sejam avaliadas todas as cousas, que aos Orfãos pertencerem, pelo Juiz e Scrivão, e duas, ou tres pessoas outras ajuramentadas, que o bem entendam. E sejam os preços das ditas cousas logo scriptos nos ditos inventarios e partilhas, para que ao tempo, em que se lhes ha de fazer entrega das ditas cousas, por serem casados, ou emancipados, ou por qualquer outra razão, se as taes cousas forem gastadas, ou danificadas, por se dellas servirem as mãis dos ditos Orfãos, se em seu poder ficarem, ou seus Tutores, se logo lhes foram entregues, se pagarem pelas ditas avaliações, e assi serão remediados os Orfãos, sem receberem perda, nem engano. Porém, se forem moveis, de que os Orfãos se servirem, não será sua mãi, ou seu Tutor obrigado a lhos entregar, senão assi como stiverem.` },
        { id: 'of1-tlxxxviii-6', number: '6', text: `E se a mãi de algum menor de vinte cinco annos se finar, o Juiz será obrigado dentro do dito mez mandar o pai desse menor, que faça inventario de todos os bens moveis e de raiz, que elle tinha e possuia ao tempo da morte da dita sua molher, dando-lhe para isso juramento dos Santos Evangelhos. E tanto que o inventario for feito, fará as partilhas e avaliações, como dito he. E deixará os bens em poder do pai, porque elle per Direito he seu legitimo Administrador. Porém he obrigado conservar os bens a seus filhos, quanto á propriedade, e sómente póde gastar as rendas e novidades dos ditos bens, em quanto tiver seus filhos em poder, e he obrigado a entregar-lhos pelo inventario; quando forem emancipados, ou casarem; porque segundo stilo de nosso Reino, sempre como o filho he casado, he havido por emancipado, e fóra do poder de seu pai. Porém, se forem moveis, de que os Orfãos se servirem, ou em seu uso se gastarem, não será o pai obrigado a lhos entregar, senão assi como stiverem. E se o pai for torcado do entendimento, ou doente de tal enfermidade, que não possa reger, ou administrar os bens de seus filhos, não lhe serão entregues os bens, que aos ditos filhos pertencerem por morte de sua mãi, mas ser-lhes-ha dado Tutor, ou Curador, na maneira que per nossas Ordenações stá provido.` },
        { id: 'of1-tlxxxviii-7', number: '7', text: `E mandará fazer inventario de toda a fazenda e bens, que á algum menor de vinte cinco annos pertencer herdar, ou haver por morte de alguma pessoa, do dia, que souber que lhe pertencem, a hum mez, na maneira que acima mandamos que se faça, quando lhe morre pai, ou mãi. E todo o que dito he, cumprirá o dito Juiz, sob pena de privação do Officio.` },
        { id: 'of1-tlxxxviii-8', number: '8', text: `E mandamos que por fallecimento do marido, ou da molher, cada hum delles, que vivo ficar, a que ficarem filhos, ou netos menores de vinte cinco annos, dentro de dous mezes do dia do dito fallecimento, quando ainda per mandado do Juiz dos Orfãos não tiver feito inventario, postoque per elle lhe não seja mandado, que o faça, seja obrigado de fazer inventario de todos os bens moveis e de raiz, que por morte do defunto ficarem, com as declarações acima ditas, o qual fara com o Scrivão dos Orphãos, per juramento dos Santos Evangelhos, que per Juiz lhe será dado; e o juramento se assentará pelo dito Scrivão, em cuja mão ficará o inventario, assinado per aquelle, que o fizer, para em todo o tempo se poder delle ajudar a pessoa, ou pessoas, a que pertencer. E não o fazendo assi dentro no dito tempo e pelo modo que dito he, o pai ou avô, que o assi não fizer, por esse mesmo feito será privado da herança dos filhos, ou descendentes, que ao tal tempo tiver, para nunca mais em tempo algum lhes poder succeder; e mais se for seu pai, será privado do uso e fructo de seus bens. E se for mãi, ou avó, além da privação da herança, nenhuma dellas poderá ser sua Tutor, nem ter mais seus filhos em sua governança.` },
        { id: 'of1-tlxxxviii-9', number: '9', text: `E o pai, ou mãi, ou qualquer outra pessoa, que per mandado da Justiça fizer inventario, e nelle sonegar e encobrir alguma cousa, assi movel, como de raiz, que fosse do defunto ao tempo de seu falecimento, perderá para os menores tudo aquillo, que sonegar. E não haverá parte alguma (se a tiver) do que sonegar, e mais pagará em dobro para os menores a valia das cousas, que assi sonegar, e não poser no inventario, postoque nas ditas cousas, que assi sonegou, não tenha parte alguma. E além disso haverá a pena de perjuro.

Criação.` },
        { id: 'of1-tlxxxviii-10', number: '10', text: `E se alguns Orfãos, nascidos de legitimo matrimonio, ficarem em tão pequena idade, que hajam mister criação, dal-os-hão a criar á suas mãis, se as tiverem, em quanto se ellas não casarem. A qual criação serão obrigadas fazer aos Orfãos haverem tres annos cumpridos: e isto de leite sómente, sem por isso levarem cousa alguma; e todo o al lhes será dado dos bens dos ditos Orfãos, confórme ao que na cidade, villa, ou lugar, se costuma dar ás Amas por criação de meninos. E esta criação se pagará até o tempo, que os Orfãos sejam em idade, em que possam merecer alguma cousa por seu serviço. Porém, se alguma mãi for de tal qualidade e condição, que não deva com razão criar seus filhos ao peito, ou por algum impedimento os não possa criar, será o Orfão dado á Ama, que o crie assi de leite, como de toda a outra criação, que lhe for necessária, á custa dos bens dos ditos Orfãos. E se não tiverem bens, per que se possa pagar sua criação, suas mãis serão constrangidas que os criem de graça de toda criação, até serem de idade, em que possam merecer soldada.` },
        { id: 'of1-tlxxxviii-11', number: '11', text: `Porém, se as crianças, que não fôrem de legitimo matrimonio, forem filhos de alguns homens casados, ou de solteiros, primeiro serão constrangidos seus pais, que Silva Pereira, parecendo partilhar a opinião do Desembargador Themudo, afirma que no seu tempo se julgava de conformidade com a opinião negativa.

Barbosa, no respectivo Com.; Cabedo—Decisões, p. 1 Ar. 73; e Fragoso—de Regimine Reipublica, t. 1 disp. 15, defender a negativa. A opinião contrária sustentão Pegas, e Corrêa Telles—Doutrina das Acções, § 455 nota, e; Paiva e Pona, obra citada cap. 8 n. 41.

Mas, cessando a razão da lei, póde-se confiar o orphão á sua mãi, ainda que tenha passado a segundas nupcias. Pegas, no respectivo Com., ns. 16 e 17.

E assim se observa.

A criação de leite por tres annos era de rigor na antiguidade, e talvez á esta circumstancia se deva o serem aquellas gerações mais fortes que as modernas. Na Biblia tambem se encontra este preceito.

os criem, e não tendo elles por onde os criar, se criarão á custa das mãis. E não tendo elles nem ellas por onde os criar, sejam requeridos seus parentes, que os mandem criar. E não o querendo fazer, ou sendo filhos de Religiosos, ou de molheres casadas, os mandarão criar á custa dos Hospitaes, ou Albergarias, que houver na cidade, villa ou lugar, se tiver bens ordenados para criação dos engeitados: de modo que as crianças não morram por falta de criação. E não havendo hi taes Hospitaes e Albergarias, se criarão á custa das rendas do Concelho E não tendo o Concelho rendas, per que se possam criar, os Officiaes da Camera lançarão finta pelas pessoas, que nas fintas e encarregos do Concelho hão de pagar.` },
        { id: 'of1-tlxxxviii-12', number: '12', text: `Item, se o Juiz dos Orfãos achar, que algumas pessoas criaram alguns Orfãos pequenos, sem levarem por sua criação algum preço, se a criação fizeram antes de os Orfãos chegarem a idade de sete annos, a estes, que assi criaram, deixarão ter de graça outros tantos annos, quantos os assi criaram sem preço.

Soldada.` },
        { id: 'of1-tlxxxviii-13', number: '13', text: `E quando se alguns Orfãos houverem de dar por soldada, ou a pessoas, que se hajam de obrigar de os casar; tanto que fôrem de idade de sete annos, o Juiz dos Orfãos fará lançar pregão no fim de suas audiencias, em que digam, que tem Orfãos para se darem por soldada, ou por obrigação de casamento, que quem os quizer tomar vá á sua casa, e que lhes dará; não nomeando no pregão que Orfãos são, nem cujos filhos. E não os dará, senão em sua casa a quem por elles mais soldada dér. E fará obrigar per scripturas publicas áquelles, a que os dér, que lhes pagarão seus serviços, casamentos, ou soldadas, segundo lhes forem dadas, aos tempos, que se obrigarem pagar, para o que darão fiadores abastantes a o assi cumprirem. E se alguns Orfãos forem filhos de Lavradores, e outros Lavradores os quizerem para mister da lavoura, não lhes serão tirados tanto por tanto. E se suas mesmas mãis os houverem mister para lavoura, e forem viuvas, que viverem honestamente, a ellas se dêm primeiro tanto por tanto. E não tendo mãis, se seus avós os quizerem para o dito mister, a elles se dêm. E não tendo avós, se outros parentes tiverem, e para o dito mister da lavoura os quizerem, a elles sejam dados, preferindo sempre os parentes A lei não fixa a soldada do Orphão, deixando-a ao prudente arbitrio do Juiz.

tes mais chegados até o quarto grão. E havendo dous em igual grão, precederá o da parte do pai, que fôr mais abastado. E o Juiz, que isto não cumprir, pagará ao Orfão toda a perda e dano, que por isso se lhe causar. E o Juiz, que o filho do Lavrador dér a quem não for Lavrador, para outro serviço, achando Lavrador, que o queira tomar, pagará mil réis: e o Tutor, que em tal dada consentir outros mil, ametade para quem os accusar, e a outra para as obras do Concelho. E não tolhemos aos Lavradores, a que os Orfãos forem dados principalmente para lavrar, servirem-se delles em guardar gado e bestas e outros serviços, quando lhes cumprir, com tanto que principalmente os occupem na lavoura. E em todo o caso, quando o Orfão se houver de dar por soldada, não será tirado a sua mãi, em quanto se não casar, ou a seus avós tanto por tanto.` },
        { id: 'of1-tlxxxviii-14', number: '14', text: `E o Juiz dos Orfãos ou Scrivão dante elle, não tomarão para si por soldada, nem em outra maneira Orfão algum de sua jurisdição, postoque lhe queiram dar mais soldada, que outra pessoa, sob pena de perderem os Officios e mais a soldada, que prometerem anoveado, ametade para quem accusar, e a outra para o Orfão.` },
        { id: 'of1-tlxxxviii-15', number: '15', text: `Se alguns Orfãos forem filhos de taes pessoas, que não devam ser dados por soldadas, o Juiz lhes ordenará o que lhes necessario for para seu mantimento, vestido e calçado, e todo o mais em cada hum anno. E o mandará screver no inventario, para se levar em conta a seu Tutor, ou Curador. E mandará ensinar a ler e screver aquelles, que forem para isso, até idade de doze annos. E dahi em diante lhes ordenará sua vida e ensino, segundo a qualidade de suas pessoas e fazenda.` },
        { id: 'of1-tlxxxviii-16', number: '16', text: `E se forem filhos de Officiaes mechanicos, serão postos a aprender os officios de seus pais, ou outros, para que mais pertencentes sejam, ou mais proveitosos, segundo sua disposição e inclinação, fazendo scripturas publicas com os Mestres, em que se obriguem a os dar ensinados em aquelles officios em certo tempo arrazoado, obrigando para isso seus bens. E o Tutor, ou Curador com auctoridadc do Juiz obrigará os bens dos Orfãos e suas pessoas a servirem os ditos Mestres per aquelle tempo no serviço, que taes aprendizes costumam fazer. E o Juiz, que isto não cumprir, pagará ao Orfão toda a perda e dano, que por isso se lhe causar.` },
        { id: 'of1-tlxxxviii-17', number: '17', text: `E se os Orfãos fugirem por culpa de seus amos, que os tinham, por os tratarem mal, serão constrangidos a lhes pagar aquelle tempo, que os serviram, sem os Orfãos serem obrigados a acabar de servir o tempo da obrigação. E se a fugida for por culpa dos Orfãos, serão constrangidos a tornar a servir todo o tempo conteúdo na obrigação, e mais outro tanto, quanto deixaram de servir, por andarem fugidos por sua culpa, não passando de seis mezes todo o tempo, que por pena houverem de servir. Porém se aquelles, que os tinham, não quizerem que os acabem de servir, não serão obrigados a os tomar, não lhe sendo tornados dentro de hum mez do dia, que fugiram. E se algum dinheiro tiverem recebido dante mão, tornal-o-hão soldo à livra do tempo, que o Orfão servio.` },
        { id: 'of1-tlxxxviii-18', number: '18', text: `E defendemos que nenhuma pessoa, de qualquer qualidade que seja, não tome nenhum Orfão, nem se sirva delle no lugar, onde tiver seu Tutor, ou Curador, sem lhe ser dado pelo dito Tutor, ou Curador com auctoridadc do Juiz dos Orphãos. O qual, quando os houver de dar por soldada, os dará a pessoas, de que sejam bem tratados, e com as seguranças e condições atraz declaradas. E qualquer pessoa, que os ditos Orfãos de outra maneira tomar, ou se servir delles, pagará por cada mez ao Orfão mil réis, e outro tanto aos Captivos. E o Tutor, ou Curador, que deixar assi star o dito Orfão, pagará esta pena em dobro. E o Juiz, que nisso for negligente, pola primeira vez será suspenso do Officio hum anno; e pola segunda o perderá, e pagará outro tanto, como ha de pagar a pessoa, que assi tiver o dito Orfão sem sua licença. E tomando-o fóra do lugar, onde tiver seu Tutor, ou Curador, pagará ao dito Orfão o que merecer pola soldada.

Casamentos.` },
        { id: 'of1-tlxxxviii-19', number: '19', text: `E se algum Orfão, ou menor de vinte cinco annos, que tiver Tutor, ou Curador, se casar sem auctoridade do Juiz dos Orfãos, e o casamento for feito per vontade do Orfão, ou menor, sem induzimento de pessoa alguma, e for o casamento menos daquillo, que o Orfão, ou menor poderá achar, segundo a qualidade de sua pessoa, e da fazenda, que tiver, não lhe mandará o Juiz entregar seus bens, até chegar à idade de vinte annos. E postoque haja Carta nossa, ou dos nossos Desembargadores do Paço, para que lhe sejam entregues, se nella se não fizer expressa menção, como assi se casou sem auctoridade do Juiz dos Orfãos, o dito Juiz não cumprirá tal Carta nem lhe mandará entregar seus bens, até chegar à idade de vinte annos. E esta pena haverá outro qualquer, que sem auctoridade do Juiz casar com alguma Orfã, ou menor de vinte cinco annos, que Tutor, ou Curador tiver.` },
        { id: 'of1-tlxxxviii-20', number: '20', text: `E casando algum Orfão sem auctoridade do Juiz dos Orfãos, postoque Tutor, ou Curador não tenha, per engano ou induzimento, que lhe per alguma pessoa seja feito, aquelle que o assi enganou, ou induziu, será constrangido perfazer ao dito Orfão sobre a fazenda da dita pessoa, com quem assi casou, tanto quanto lhe devêra ser dado em casamento com o dita pessoa, com que assi casou.` },
        { id: 'of1-tlxxxviii-21', number: '21', text: `E se algum Tutor, ou Curador induzir a algum Orfão, ou menor de idade de vinte cinco annos, cujo Tutor ou Curador for, e o casar sem auctoridade do Juiz dos Orfãos, será constrangido dar de sua fazenda ao dito Orfão outro tanto, quanto elle tiver. E além disso será preso até nossa mercê, e pagará para nossa Camera o quinto daquillo, que per bem deste Regimento ha de satisfazer ao Orfão não se descontando polo tal quinto cousa alguma do que ao dito Orfão mandamos dar.

Bens dos Orfãos.` },
        { id: 'of1-tlxxxviii-22', number: '22', text: `E terá cuidado o Juiz dos Orfãos de saber, como os bens delles são aproveitados. E se o não forem, faça-os aproveitar logo; e os que danificados forem, saiba por cuja culpa. E pelos bens dos que nisso forem culpados, os faça aproveitar e tornar a seu stado com os fructos e rendas, que delles poderam haver, se aproveitados foram.` },
        { id: 'of1-tlxxxviii-23', number: '23', text: `E constrangerá aos Tutores, que arrendem os bens, que forem para arrendar; os quaes farão metter em pregão os ditos bens, e arrematar a quem por elles mais der, sendo sempre as ditas arrematações com auctoridade do Juiz dos Orfãos. E achando que não dão por elles cousa arrazoada, os fará aproveitar aos Tutores, ou Curadores. E o que renderem de fructos, ou novidades, receberão os Tutores per conta e recado, e lhes será carregado em receita no livro do inventario do Orfão, ou menor, pelo Scrivão do dito Officio. E não farão contractos alguns dos bens e dinheiro dos Orfãos, em que haja alguma specie de usura, nem consentirão Pegas sustenta a negativa, apoiado em um caso julgado.

que se façam; e fazendo-se, o que assi fizer, incorrerá nas penas conteúdas no Livro quarto, Título 67: Dos contractos usurarios, assi como incorrêra, se o tal dinheiro, ou bens foram seus. Porém o dinheiro, ou bens dos Orfãos não se perderão por isso.` },
        { id: 'of1-tlxxxviii-24', number: '21', text: `E tendo o Orfão bens em outro lugar fóra da jurisdição do dito Juiz, elle screverá com diligencia ao Juiz do lugar, onde os ditos bens stiverém, dando-lhe declaradamente a informação do negocio, e requerendo-lhe de nossa parte, que faça logo dar hum Curador abonado a esses bens, e lhos faça entregar per scripto, sendo-lhes primeiro dado juramento, que os administrará bem e fielmente, e dará conta delles e dos fructos e rendas, que renderem, a todo o tempo, que para isso for requerido. E o dito Juiz terá cuidado de haver a resposta per scripto do outro Juiz, a que tal recado enviar, e da obra, que per elle fez. O que tudo se screverá no inventario dos bens do dito Orfão, para vir a boa arrecadação. E faça de tal maneira, que por sua culpa e negligencia os bens dos Orfãos não recebam dano, porque todo o dano e perda, que receberem, pagará per seus bens.` },
        { id: 'of1-tlxxxviii-25', number: '25', text: `E achando que os Orfãos têm bens moveis, que será mais seu proveito venderem-se, mandal-os-ha vender em pregão em almoeda, a quem por elles mais dér. E do dinheiro que se delles fizer, e de qualquer outro que tiver, mandará aos Tutores e Curadores, que com sua auctoridade comprem bens de raiz para os ditos Orfãos, que lhes rendam. E achando herdades de pão, antes as comprem, que vinhas, nem outras heranças, que hajam mister adubios. E destas heranças, que assi comprarem, faça o Juiz fazer as scripturas das compras com toda a segurança, que para os Orfãos for necessaria, em maneira, que os bens, que comprarem, não lhes possam ser em algum tempo tirados, por se dizer, que não eram dos vendedores, ou por defeito de alguma solemnidade nas ditas scripturas. E antes de se fazerem as compras, fará toda a diligencia, que cumprir, para se saber se esses bens são livres e desembargados, e sem obrigação a alguma pessoa, por onde a venda não fique firme e segura.` },
        { id: 'of1-tlxxxviii-26', number: '26', text: `E em nenhum caso se venderão bens de raiz dos Orfãos, ou menores, salvo por tal necessidade, que se não possa escusar. E quando se assi houverem de vender, vender-se-ha a propriedade, que menos proveitosa for ao Orfão. E vendendo-se de outra maneira, a venda seja nenhuma, e o Tutor, ou Curador, que a fizer, e o Juiz, que a ella dér sua auctoridade, pagarão ao Orfão toda a perda e dano, que per razão da dita venda receber.` },
        { id: 'of1-tlxxxviii-27', number: '27', text: `E defendemos ao Juiz dos Orfãos, que não mande entregar os bens a nenhum Orfão, salvo se houver vinte cinco annos perfeitos, ou for casado per sua auctoridade depois de haver dezoito annos, ou levar Carta de suprimento de idade, passada pelos Desembargadores do Paço, como diremos no Livro terceiro, Título 42: Do Orfão menor de vinte cinco annos, que impetrou graça: e não per outros Officiaes, nem Corregedores, nem Provedores.` },
        { id: 'of1-tlxxxviii-28', number: '28', text: `E havendo o menor tal Carta, ou sendo casado e de idade de vinte annos, sendo-lhe seus bens entregues per virtude da tal Carta, ou casamento, será dahi em diante em todo caso havido por maior do vinte cinco annos. Em tanto que vendendo elle, ou emlheando, ou obrigando alguma possessão de raiz, com consentimento e au- clotidade de Justiça, aindaque seja leso e danificado, não poderá usar do beneficio de restituição, que per direito he outorgado aos menores, quando são lesos. E fazendo elle a dita emlheação, ou obrigação sem auctoridade de Justiça, o tal contracto será nenhum e de nenhum valor, assi como se o dito menor não houvesse impetrada a dita Carta, ou não fosse casado.` },
        { id: 'of1-tlxxxviii-29', number: '29', text: `E mandamos que os Tutores e Curadores não comprem per si nem per outrem bens moveis, nem de raiz das pessoas, cujos Tutores, ou Curadores forem, posto que por elles queirão dar sua justa valia. E postoque se vendam per mandado da Justiça publicamente em pregão, não lhes poderão os Juizes dar licença para os comprarem. E comprando-os, ou havendo-os, não valha a tal venda, ou contracto; antes seja nullo e de nenhum effeito, e percam anoveado o preço, que por elles derem, ametade para o Órfão, e a outra para quem os accusar. Nem poderão haver os ditos bens em tempo algum per nenhum titulo, ainda depois de não serem Tutores, salvo per via de successão. Porém, se se venderem alguns outros bens depois de o Tutor, ou Curador deixar de o ser, os poderá haver e comprar, porque já então cessa a presunção da fraude.` },
        { id: 'of1-tlxxxviii-30', number: '30', text: `E bem assi o Juiz e Scrivão não tomarão, nem comprarão per si, nem per outrem, nem receberão, nem terão em seu poder dinheiro algum, ou bens, ou quaesquer outras cousas, que sejam dos ditos Orfãos. E postoque se lhes não prove, nem allegue serem compradas, sómente por lhes assi serem achadas em seu poder, ou lhes ser provado, que em seu poder tiveram o dito dinheiro, queremos que per- cam os Officios, e paguem o dinheiro, que assi tomarem, ou receberem, e tornem as ditas cousas, sendo havidas, ou sua estimação, não sendo havidas, e tudo o sobredito anoveado para o Orfão. E ficarão inhabiles para nunca poder haver Officio de honra: e as ditas vendas serão nenhumas.

Arca.` },
        { id: 'of1-tlxxxviii-31', number: '31', text: `Mandamos, que o dinheiro dos Orfãos se deposite em huma arca com tres chaves, em poder de hum Depositário, pessoa abonada, que haverá em cada cidade, villa e Concelho.` },
        { id: 'of1-tlxxxviii-32', number: '32', text: `Outrosi mandamos aos Corregedores das Comarcas, que de dous em dous annos, quando forem fazer correição, em cada hum dos lugares de sua Comarca se ajuntem em Camera com os Juizes, Véreadores e Procuradores; os quaes lhes nomearão alguns homens de bem e abonados da tal cidade, villa, ou Concelho, para terem o dito dinheiro depositado. Dos quaes, ou de outros, que assi houver, cada hum dos ditos Corregedores, com o parecer dos ditos Officiaes, elegerá huma pessoa abonada que mais apta lhe parecer para ter o dito deposito, e lhe mandará de nossa parte, que se encarregue disso per tempo de dous annos. E mandará fazer à custa do dinheiro dos Além da pena do referido artigo, a acquisição em todo o caso será nulla.

A antiga legislação punia com mais rigor. Pegas, no respectivo Com., refere que pela transgressão desta Ord. foi no seu tempo decapitado o Juiz de Orphãos João Teixeira Delgado, e enforcado o Escrivão João Baptista Ramos.

Os que sustentão a affirmativa apoião-se na Ord. deste liv. t. 62 § 7.

Orfãos huma arca com tres chaves de diferentes guardas; das quaes terá o Juiz dos Orfãos huma, o Depositário outra e o Scrivão dos Orfãos outra: e onde houver mais que hum Scrivão, tel-a-ha o mais antigo no Officio. E o Scrivão, que tiver a dita chave, terá na arca dous livros, hum para a receita, e outro para a despesa do dinheiro, que se houver de metter e tirar della. Os quaes livros serão encadernados, e de tantas folhas, e intitulados hum como o outro, e as folhas serão contadas e assinadas, segundo fórma de nossas Ordenações, sob as penas nellas conteudas, e serão assinadas pelo Provedor da Comarca. Os quaes livros não se tirarão da arca, senão quando se nelles houver de screver.` },
        { id: 'of1-tlxxxviii-33', number: '33', text: `E para mais facilmente se acharem no dito livro as Tutorias de cada hum dos Orfãos, se fará no começo delle hum título de todas as Tutorias dos Orfãos da villa de tantas folhas, que possam nelle caber além das Tutorias que então houver, as mais que depois sobrevierem. E em outra parte do livro fará outro título das Tutorias dos Orfãos do termo, fazendo de cada vintena, Julgado, ou quadrilha, título apartado, na maneira sobredita. E em cada hum dos ditos títulos ficarão tantas folhas em branco entre huma Tutoria, e outra, em que possa caber o que se houver de deitar em receita, ou despesa. E em cada título se declararão os nomes dos Orfãos e do pai e mãi, e alcunhas, dos tiverem. E tanto que cada hum dos ditos livros for de todo scripto, se fará outro na fórma acima dita.` },
        { id: 'of1-tlxxxviii-34', number: '34', text: `E todo o dinheiro, que os Orfãos tiverem, por lhes ficar por fallecimento de seu pai, ou mãi, ou de dividas, que se lhes devam, ou rendimentos da sua fazenda, tanto que for na mão do Tutor, elle será obrigado a logo requerer ao Juiz, para com o Scrivão o irem metter na arca do deposito. E quando se metter na dita arca, se fará assento pelo Scrivão dos Orfãos no livro da receita, no título da tal Tutoria, carregando-se sobre o dito Depositário, com declaração de seu nome, e da quantidade do dinheiro, e de quem se arrecadou, e a quem se entregou, e do dia, mez e anno, em que assi se carrega: o qual assento será assinado pelo Depositário. E o Scrivão, que tiver o inven- tario de tal Orfão, fará nelle outro tal assento, com as mesmas declarações, no qual assinará o Juiz dos Orfãos.` },
        { id: 'of1-tlxxxviii-35', number: '35', text: `E na dita arca se metterão todas as pedras, perolas, joias, ouro e prata, que aos Orfãos pertencerem, com declaração dos nomes, peso, conto, valia e sinaes de cada peça, além das declarações sobreditas do livro e do inventário; e esta mesma ordem se terá cada vez que se metter, ou tirar da dita arca dinheiro, ou cada huma das sobreditas cousas.` },
        { id: 'of1-tlxxxviii-36', number: '36', text: `E querendo o Tutor, para sua guarda e lembrança, certidão do dinheiro, ou cousas, que tiver na arca, o Juiz lha mandará dar, feita pelo Scrivão, e assinada per elle.` },
        { id: 'of1-tlxxxviii-37', number: '37', text: `E quando se houver de tirar dinheiro, ou alguma das ditas cousas da arca, assi para se comprarem bens de raiz, como para se entregar aos Orfãos, por serem casados, ou emancipados, ou de idade perfeita, ou per qualquer outra maneira, que segundo fórma das Ordenações e Regimento se deva despender: o Scrivão, que tiver a chave, fará assento no livro da despesa, no título do Orfão, cujo for, declarando o dia, mez e anno, em que se tira, e para que, e per cujo mandado, e a quem se entrega, e o nome do Depositário, que o entrega. O qual assento será assinado pelo Juiz e pela parte, que o receber.` },
        { id: 'of1-tlxxxviii-38', number: '38', text: `E antes que o dinheiro se metia na arca, o Juiz com os Partidores taxará a despesa necessaria para o Orfão naquelle anno, segundo sua qualidade, não sendo tal, que haja de ser dado por soldada, nem tendo outros bens, de que se possa alimentar. E a dita despesa poderá o Juiz deixar na mão do Tutor, para despender com o Orfão naquelle anno.` },
        { id: 'of1-tlxxxviii-39', number: '39', text: `E a dita arca se não abrirá, senão sendo presentes o Juiz, Depositario e Scrivão, que tiverem as chaves. E se o Juiz ou Scrivão forem impedidos, em modo que não possam ser presentes, dará cada hum delles a sua chave à pessoa que por elle servir ao tempo, que assi for impedido, de maneira que em nenhum tempo possa huma só pessoa ter duas chaves.` },
        { id: 'of1-tlxxxviii-40', number: '40', text: `E passados os dous annos, em que o Depositario servir o dito cargo, ou tendo tal impedimento, por onde não possa acabar de servir os ditos dous annos, se fará outro Depositario novo, na maneira acima dita. E antes que se lhe entregue a arca e chave, o Provedor com o Juiz dos Orfãos, sendo presente o Scrivão, que tiver a chave, tomará conta ao Depositario passado, e o que não for despesa, fará entregar logo ao Depositario novo: e se fará hum termo no livro da receita do que assi lhe for entregue, com declaração da somma do dinheiro e cousas, que na arca stiverem, e cujas são. No qual termo assinarão o Provedor e Juiz, Depositario e Scrivão.` },
        { id: 'of1-tlxxxviii-41', number: '41', text: `E o Scrivão, que tiver a chave, terá hum livro em seu poder fóra da arca, em que fará o auto da entrega da arca e cousas, que nella se metteram, e que o primeiro Depositario entregou ao novo: e dahi em diante, quando se houver de entregar de hum Depositario a outro. E no dito livro trasladará os termos das entregas, que se fizerem aos Depositarios. Nos quaes autos assinarão as mesmas pessoas, que assinarém no termo do livro, que ficar na arca.` },
        { id: 'of1-tlxxxviii-42', number: '42', text: `E pedindo o Depositario passado quitação do que sobre elle carregava, depois de ter tudo entregue, ser-lhe-ha passada pelo Scrivão dos Orfãos, e assinada pelo Juiz e Provedor. Na qual se trasladará o termo da entrega do que stiver na arca ao tempo, que o Depositario passado a entregar ao Depositario novo. E tudo o que dahi em diante se houver de receber e despender pelo Depositario novo, se assentará e assinará pela maneira e pessoas acima ditas.` },
        { id: 'of1-tlxxxviii-43', number: '43', text: `E os que forem eleitos para Depositarios, não serão escusas do dito carrego, senão naquelles casos, e aquellas pessoas, que podem ser escusas dos Officios de Juizes, Véreadores, Procuradores e Almotacés, segundo fórma de nossas Ordenações.` },
        { id: 'of1-tlxxxviii-44', number: '44', text: `E os Depositarios que assi não cumprirem as cousas nesta Ordenação declaradas, no que a cada hum delles toca, serão degradados dous annos para Africa, e pagará cada hum vinte cruzados, ametade para os Captivos, e a outra para quem os accusar. E mais serão obrigados pagar aos Orfãos a perda e dano, que lhes causar sua negligencia. E o Provedor, Juiz e Scrivão que não cumprirem o que a seus Officios toca acerca dos ditos depositos, além da sobredita pena, perderão seus Officios. E huns e outros haverão as mais penas, que segundo a qualidade de suas culpas per Direito merecerem.

Jurisdicção.` },
        { id: 'of1-tlxxxviii-45', number: '45', text: `E terá o Juiz dos Orfãos jurisdicção em todos os feitos civeis, em que os Or- fãos sejam autores, ou réos, emquanto não forem emancipados, ou casados, e nos feitos dos Desasisados, ou Prodigos, ou Desmemoriados, que Curadores tiverem. E postoque nas cousas demandadas, ou aucões, sobre que se litiga, alguns maiores tenham parte, por ainda não terem partido, todavia se tratará a demanda perante o Juiz dos Orfãos, assi pelo que pertence aos Orfãos e menores, como pelo que pertence aos maiores: salvo se as contendas forem com outros Orfãos, ou pessoas privilegiadas de semelhantes privilegios; por que em taes casos o autor seguirá o foro do réo.` },
        { id: 'of1-tlxxxviii-46', number: '46', text: `E assi terá o Juiz dos Orfãos jurisdicção em todos os feitos civeis, que se per os Orfãos (postoque emancipados, ou casados sejam), moverem sobre partilhas, ou inventarios, ou quando quizerem demandar seus Tutores, ou Juizes dos Orfãos, ou Provedores passados, sobre a entrega, ou má governança de sua fazenda. E as appellações irão a cada huma das Relações a que pertencerem.` },
        { id: 'of1-tlxxxviii-47', number: '47', text: `E sendo Juizes de fóra dos Orfãos, postos per Nós em algumas cidades e villas de nossos Reinos, e bem assi os da cidade de Lisboa, terão alçada, até quantia de cinco mil réis nos bens moveis, e até quatro mil réis nos bens de raiz, e nas penas que pozerem, até mil réis. E as sentenças, que derem até as ditas quantias, e assi as ditas penas, darão à execução sem appellação, nem aggravo.

que respeita à jurisdicção do Juiz de Orphãos, quanto aos ausentes.

Tambem se chama alçada a commissão que outr'ora se dava para ir devassar de um ou mais delicto a certo ou certos Magistrados, e a respeito fazer a devida justiça.` },
        { id: 'of1-tlxxxviii-48', number: '48', text: `E nos feitos crimes não se entremetterá o Juiz dos Orfãos, porque o conhecimento delles pertence aos Juizes ordinarios.

Salarios.` },
        { id: 'of1-tlxxxviii-49', number: '49', text: `E os Juizes dos Orfãos por fazer qualquer partilha dos Orfãos haverão sómente dez réis por milheiro até quantia de trinta mil réis, em que devem haver trezentos réis. Porém se a fazenda valer quatrocentos mil réis, levará o Juiz oitocentos réis. E por fazer qualquer inventario não leve mais que dous vintens. E de tomar a conta a qualquer Tutor, não leve mais que sessenta réis; e estas contas não tomarão aos Tutores, ou Curadores dativos, senão de dous em dous annos, que ha de durar a sua Tutoria, ou Curadoria. E a legitimos, ou testamentarios não tomarão conta, senão de quatro em quatro annos, se tanto durar a Tutoria, ou Curadoria. E bem assi a huns e outros no fim do tempo da Tutoria, ou Curadoria.` },
        { id: 'of1-tlxxxviii-50', number: '50', text: `Porém cada vez que o Juiz dos Orfãos for informado, que algum dos Tutores, ou Curadores rege mal a Tutoria, ou Curadoria, logo lhe tomará a conta. E, achando que o fez mal, o privará della, e fará outro Tutor, ou Curador; ao qual fará entregar todos os bens do Orfão, ou menor, constrangendo ao Tutor ou Curador removido, que logo entregue tudo ao Tutor, ou Curador novo, com todas as perdas e danos, que o Orfão, ou menor recebeu por culpa, ou negligencia do removido.` },
        { id: 'of1-tlxxxviii-51', number: '51', text: `E não consentirá o Juiz aos Parti- dores, que as partilhas dos Orfãos fizerem, que levem mais de dez réis por milheiro, até quantia de trinta mil réis, em que monta a ambos os Partidores trezentos réis. E se os bens de que fizerem partilha, menos valerem, levarão ao dito respeito: E valendo mais, levarão sómente os ditos trezentos réis, quer se façam as partilhas na cidade, villa, ou lugar, quer em seu termo. Porém, se a fazenda dos ditos Orfãos valer quatrocentos mil réis, levarão os Partidores ambos oitocentos réis. E quer a partilha se faça na villa, quer no termo, não comerão o Juiz, nem Partidores, nem Servião á custa dos Orfãos, postoque para o poderem fazer tenham quaesquer sentenças. E fazendo o contrário, ou levando mais do que dito he, haverão as penas conteidas no quinto Livro, no Titulo 72: Da pena, que haverão os Officiaes, que levam mais do conteúdo em seu Regimento.` },
        { id: 'of1-tlxxxviii-52', number: '52', text: `E se o Juiz dos Orfãos levar salario algum de inventario, partilha, ou conta, a que não stiver presente, por esse mesmo feito perca o Officio para a pessoa, que o accusar, sendo para o Officio idoneo; e não o sendo, Nós lhe daremos lugar que o possa vender, ou lhe faremos outra mercê, que nos bem parecer. E fazendo outrem a conta por absencia, ou impedimento do Juiz, ou havendo em algum lugar Official deputado para tomar as ditas contas, não levará dellas mais do que per este Regimento o dito Juiz póde levar.` },
        { id: 'of1-tlxxxviii-53', number: '53', text: `E para que os Tutores e Curadores com melhor vontade aproveitem e administrem os bens dos Orfãos, haverão por seu trabalho em cada hum anno a vintena do que os bens renderem, não passando a vintena de cincoenta mil réis em cada hum anno. E isto se entenderá não sómente nos Tutores, ou Curadores dativos, mas ainda nos parentes, a que for encarregada a Tutoria, ou Curadoria: e bem assi nos que forem deixados em testamento. Porém os que forem deixados em testamento, poderão escolher haver a dita vintena, ou o que pelo Testador lhes for deixado. E as ditas vintenas não haverão lugar no que o Orfão, ou menor ganhar por soldada. E os ditos Tutores, ou Curadores não receberão, nem tomarão para si a dita vintena, senão per Alvarás, assinados pelo Juiz, e feitos pelo Servião dos Orfãos; o qual levará por cada Alvará destes, oito réis sómente á custa do Tutor.

Fiança.` },
        { id: 'of1-tlxxxviii-54', number: '51', text: `E para que os Orfãos, tenham mais segurança de suas fazendas, mandamos que os Juizes dos Orfãos das cidades e villas principaes de nossos Reinos sejam obrigados, tanto que os ditos Officios houverem, antes de os começarem servir, darem fiança de quatrocentos mil réis, de fiadores abonados, que se obriguem a compor e pagar toda a perda e dano, que por malicia, ou culpa dos ditos Juizes se seguir aos Orfãos, até a quantia da dita fiança. A qual será desaforada com declaração que os Orfãos haverão o seu per cada hum delles in solidum, qual os Orfãos mais quizerem, e pelo melhor parado. E esta fiança será scripta per Tabellião publico das Notas, e trasladada no livro da Camara, para a todos ser notorio. E nos outros lugares será a fiança de trezentos mil réis, ou duzentos, segundo a povoação e grandeza delles. E nos lugares mais pequenos será de cem mil réis. O que ficará na estimação dos Officiaes da Camara.` },
        { id: 'of1-tlxxxviii-55', number: '55', text: `E o Juiz dos Orfãos, que servir sem dar a dita fiança perderá o Officio. E os Officiaes da Camara, que o deixarem servir sem a ter dado, pagará cada hum vinte cruzados, ametade para quem os accusar, e a outra para os Captivos. E o Scrivão, que com elle servir, perca outrosi seu Officio.` },
      ],
    },
    {
      id: 'titulo-lxxxix',
      title: `LXXXIX. Dos Scrivães dos Orfãos`,
      type: 'articles',
      articles: [
        { id: 'of1-tlxxxix-preambulo', number: 'Preâmbulo', text: `Mandamos que em todas as villas e lugares, onde na villa e termo houver qua- trocentos visinhos, ou mais, haja sempre Scrivão dos Orfãos apartado. E onde os não houver, os Tabelliães da villa, ou lugares servirão o dito Officio com os Juizes ordinarios: salvo se stiverem em costume e posse antiga de haver nos ditos lugares Scrivães dos Orfãos, ou forem per Nós ordenados, sem embargo de não haver o dito numero de visinhos.` },
        { id: 'of1-tlxxxix-1', number: '1', text: `Os Scrivães dos Orfãos das cidades e villas principaes serão obrigados, antes de começarem a servir, darem fiança de duzentos mil réis. E dos outros lugares será a fiança de cento e cincoenta mil réis, ou de cem mil réis: e nos mais pequenos de cincoenta mil réis. E a quantia da fiança, que hão de dar, ficará na estimação dos Officiaes da Camara, segundo a povoação e grandeza do lugar. A qual fiança se dará na fórma, que fica dito no Titulo 88: Dos Juizes dos Orfãos. E o Scrivão dos Orfãos, que o dito Officio servir, sem dar a dita fiança, e o Juiz, que perante si o consentir servir, percam os Officios. E os Officiaes da Camara, que lho deixarem servir, pague cada hum vinte cruzados, ametade para quem os accusar, e outra para os Captivos.` },
        { id: 'of1-tlxxxix-2', number: '2', text: `E não poderá o Scrivão dos Orfãos ser Juiz ordinario, em quanto for Scrivão, aindaque o queira ser.` },
        { id: 'of1-tlxxxix-3', number: '3', text: `E será muito diligente em servir e pôr em boa arrecadação os bens e rendas dos Orfãos, e em olhar por suas pessoas. E com o Juiz delles saberá quantos Orfãos ha em sua jurisdição, e screvel-os-ha em hum livro, declarando o nome de cada hum, e cujo filho he, e de que idade, e onde vive, e com quem, e per que maneira, e quem he seu Tutor, ou Curador. E assi mesmo screverá os inventarios de seus bens moveis e de raiz na fórma e com as declarações, que dissemos no Titulo 88: Dos Juizes dos Orfãos.` },
        { id: 'of1-tlxxxix-4', number: '4', text: `E tanto que os inventarios forem feitos, assentará no fim delles as Tutorias, declarando se são testamentarias, se legitimas, ou dativas. E assentará as fianças e fiadores, e quaesquer outras obrigações, que para segurança de boa administração das Tutorias os Juizes dos Orfãos tomarêm aos Tutores, como em seu Regimento lhes he mandado.` },
        { id: 'of1-tlxxxix-5', number: '5', text: `E no fim dos inventarios screverá todos os arrendamentos, que o Juiz fizer, dos bens dos Orfãos, e contractos sobre suas pessoas, que não passarem de tres annos, ou quando os preços dos ditos arrendamentos e soldadas não passarem de sessenta mil réis. Porque todos os outros arrendamentos, que não forem das ditas qualidades, screverão os Tabelliães das Notas, como em seu titulo he declarado. E dos arrendamentos, que forem scriptos pelos Tabelliães das Notas, fará os assentos o Scrivão dos Orfãos no fim dos inventarios, e os pagamentos delles: de maneira que a receita seja certa, para se saber como se fazem as despesas dos Orfãos. As quaes outrosi assentará nos inventarios, para tudo vir a boa arrecadação, quando os Tutores derem suas contas, e fizerem entrega aos Orfãos, ou a outros Tutores novos.` },
        { id: 'of1-tlxxxix-6', number: '6', text: `E quando alguns Orfãos forem dados por soldada, declarará o Scrivão no inventario a que pessoas são dados, e per quanto tempo e soldada, e em que tempo se ha de pagar.` },
        { id: 'of1-tlxxxix-7', number: '7', text: `E porá no inventario todo o que he ordenado ao Juiz, Tutores e Partidores por seu trabalho e salario, e todas as despesas, que per mandado do Juiz forem feitas pelos Tutores e Curadores, para tudo vir a boa arrecadação.` },
        { id: 'of1-tlxxxix-8', number: '8', text: `E não tomará para si por soldada, nem per outra alguma maneira, Orfão algum de sua jurisdição, postoque lhe queira dar maior soldada, nem tomará outra cousa alguma dos ditos Orfãos, como dissemos no Titulo 88: Dos Juizes dos Orfãos, sob as penas hi declaradas.

Salarios.` },
        { id: 'of1-tlxxxix-9', number: '9', text: `Não levará mais da scriptura, que screver, assi nos inventarios, como em quaesquer outros autos, do que levam os outros Scrivães: convém a saber por cinco regras dous réis, e mais da ida, se for na villa, ou arrabalde, sete réis. E isso mesmo lhe serão contadas as idas, quando for á alguns lugares fóra da villa fazer os inventarios. E quando se fizerem as partilhas, ou se tomarem as contas aos Tutores, além do que se lhe montar ás regras, levará suas assentadas, duas em cada dia, huma pela manhã e outra á tarde, se tanto durarem as partilhas, ou contas. E de cada assentada levará sete réis: e de assentar huma Tutoria sete réis: e de assentar a dada do Orfão á soldada doze réis: os quaes pagará aquelle, que tomar o Orfão á soldada.` },
        { id: 'of1-tlxxxix-10', number: '10', text: `E dando-se algum gado de arrendamento, de que se requeira hum só termo, levará de assentar o dito arrendamento (postoque seja hum só boi, ou vacca) sete réis.` },
        { id: 'of1-tlxxxix-11', number: '11', text: `E quando assentar nos inventarios as despesas dos Orfãos, de cada assento de despesa levará quatro réis, ou ás regras, qual o Scrivão mais quizer.` },
        { id: 'of1-tlxxxix-12', number: '12', text: `E em todo o mais, em que per este Regimento não for expressamente provido o que hão de levar, levarão o que hão de levar os outros Scrivães per seu Regimento, em quanto este o não contradisser, e mais não.

Buscas.` },
        { id: 'of1-tlxxxix-13', number: '13', text: `E porque não he razão, que os Scrivães dos Orfãos, por cada vez que screverem nos inventarios, que podem algumas vezes durar vinte annos e mais, levem busca, como passa de seis mezes, mandamos que a não levem dos inventarios, mais que trinta e seis réis por anno, no fim do anno: e isto até tres annos cumpridos, em que se monta polos ditos tres annos trento e oito réis. E dahi em diante não levem busca alguma, postoque passem muito annos, que se não screva nelles, e que seja necessario buscarem-se muitas vezes, para nelles se screverem as cousas dos Orfãos. Não lhes tolhemos porém poderem levar busca dos inventarios, quando lhes forem requeridos per alguma parte, que não seja por parte dos Orfãos, ou de seus Tutores, como a podem levar os Tabelliães dos feitos retardados. E os Scrivães, que mais levarem, haverão as penas conteúdas no quinto Livro, no Titulo 72: Da pena, que haverão os Officiaes, que levam mais do conteúdo em seu Regimento.` },
      ],
    },
    {
      id: 'titulo-xc',
      title: `XC. Do Curador, que he dado aos bens do absente, e á herança do defunto, a que não he achado herdeiro`,
      type: 'articles',
      articles: [
        { id: 'of1-txc-preambulo', number: 'Preâmbulo', text: `Segundo Borges Carneiro, esta caução só se deve prestar no caso da Ord. do § 38 do t. 62 deste liv., que E a mesma ordem mandamos, que tenham os ditos Juizes nos bens dos sobreditos absentes, de que se não póde saber onde são, nem se são mortos ou vivos.` },
        { id: 'of1-txc-1', number: '1', text: `E finando-se alguma pessoa, que não tenha herdeiro algum, que sua herança deva haver, ou que a não queira aceitar, nem molher, que sua herança queira haver segundo nossa Ordenação, em tal caso o Juiz dos Orfãos o fará logo saber ao Mamposteiro Mór dos Captivos dessa Comarca, aos quaes temos feito mercê das taes heranças. E o dito Mamposteiro Mór a mandará arrecadar em nome dos Captivos, ou dirá, que a não quer aceitar. E não a querendo elle haver, ou defender, o Juiz dará Curador à herança, com o qual o Juiz fará inventario de todos os bens, que à herança pertencerem, se ainda o não tiver feito. E o dito Curador administrará a dita herança, assi como dissemos nos Curadores dos prodigos e furiosos: e bem e fielmente a defenderá das demandas, que os crédores contra ella quizerem mover, sob pena de pagar todas as perdas e danos, que por sua culpa e negligencia se recrescerem.` },
      ],
    },
  ],
};
